-- Config-only repair installer; JSON stored as literal text
assert(type(writefile)=="function" and type(makefolder)=="function", "writefile/makefolder unavailable")
local function ensure(path)
  local current = ""
  for part in path:gmatch("[^/]+") do
    current = current == "" and part or (current .. "/" .. part)
    if not (type(isfolder)=="function" and isfolder(current)) then
      pcall(makefolder, current)
    end
  end
end
