local passed = 0
for _, entry in ipairs(files) do
  local path, content = entry[1], entry[2]
  ensure(path:match("^(.*)/[^/]+$"))
  local ok, err = pcall(writefile, path, content)
  if ok and type(readfile)=="function" then
    local readOk, actual = pcall(readfile, path)
    if not readOk or actual ~= content then ok, err = false, "read-back mismatch" end
  end
  if ok then passed += 1; print("OK", path, #content) else warn("FAILED", path, tostring(err)) end
end
print(("Config restoration: %d/%d"):format(passed, #files))